Definition FEXL : list SGP.region := [(EVar 2, -10752, ELit 10752); (EVar 10, 0, ELit 272); (EAlu Instr.ALU_ADD (EVar 33) (EVar 124), 0, ELit 1)].
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              (Nat.eqb (chain j) (chain i) && CH2.blocks_eqb (nth i G.BLS []) (if (stage i <? 6)%nat then [] else BLK (chain i))
               && CH2.blocks_eqb (nth j G.BLS []) (if (stage j <? 6)%nat then [] else BLK (chain i)) &&
              if Z.eqb pc PC_MEMSET then
                (Z.eqb (SR.ps_pc ps) PC_MEMSET && Nat.eqb (stage i) 0 && Nat.eqb (stage j) 1
                 && CHA.foot_chk GT.NF G.HDECL c [] []
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 [] [] [(IA 176, 0, ELit 80)] (NEWS_MS (IA 176) (ELit 80)) (Some (IA 176)) c ps cj [] [] [] [])
                 && CL.ps_reg_is ps 10 (IA 176) && CL.ps_reg_is ps 11 (ELit 0) && CL.ps_reg_is ps 12 (ELit 80) && shz34 cells)%bool
              else if Z.eqb pc PC_LOCALE then
                (Z.eqb (SR.ps_pc ps) PC_LOCALE && CHA.foot_chk GT.NF G.HDECL c [] [] &&
                 if Nat.eqb (stage i) 1 then
                   (Nat.eqb (stage j) 2
                    && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 10240 0 [] [] (WLOC (IA 168)) (NEWS_LOC (IA 168)) None c ps cj [] [] [] [])
                    && CL.ps_reg_is ps 10 (IA 168) && CL.ps_reg_is ps 2 (SPA (-112)))
                 else
                   (Nat.eqb (stage i) 2 && Nat.eqb (stage j) 3
                    && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 10240 0 [] [] (WLOC (IA 24)) (NEWS_LOC (IA 24)) None c ps cj [] [] [] [])
                    && CL.ps_reg_is ps 10 (IA 24) && CL.ps_reg_is ps 2 (SPA (-192))))%bool
              else if Z.eqb pc PC_AMEMSET then
                (Z.eqb (SR.ps_pc ps) PC_AMEMSET && CHA.foot_chk GT.NF G.HDECL c [] [] && CL.ps_reg_is ps 11 (ELit 0) && shz34 cells &&
                 if Nat.eqb (stage i) 3 then
                   (Nat.eqb (stage j) 4
                    && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 [] [] [(IA 32, 0, ELit 48)] (NEWS_MS (IA 32) (ELit 48)) (Some (IA 32)) c ps cj [] [] [] [])
                    && CL.ps_reg_is ps 10 (IA 32) && CL.ps_reg_is ps 12 (ELit 48))
                 else
                   (Nat.eqb (stage i) 4 && Nat.eqb (stage j) 5
                    && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 [] [] [(IA 80, 0, ELit 24)] (NEWS_MS (IA 80) (ELit 24)) (Some (IA 80)) c ps cj [] [] [] [])
                    && CL.ps_reg_is ps 10 (IA 80) && CL.ps_reg_is ps 12 (ELit 24)))%bool   (* [comment removed for export] *)
              else if Z.eqb pc PC_OPNEW then
                let nx := (CC.cp_nx cj - APC.NCS)%nat in let news := news_of (nx + 4) cj in
                (Z.eqb (SR.ps_pc ps) PC_OPNEW && Nat.eqb (stage i) 5 && Nat.eqb (stage j) 6 && Nat.eqb nx 120 && (Nat.eqb (chain i) 1 || Nat.eqb (chain i) 2)
                 && CHA.foot_chk GT.NF G.HDECL c [] []
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4112 0 [] [] [] news None c ps cj [] [] (BLK (chain i)) [])
                 && CRB.fresh_news_ok 65536 7094272 G.HDECL GT.SCELLS GT.GLO GT.GHI cells nx [] [] (nx + 4) (SZ (chain i)) news
                 && CL.ps_reg_is ps 10 (SZ (chain i)))%bool
              else if Z.eqb pc PC_MEMCPY then
                (Z.eqb (SR.ps_pc ps) PC_MEMCPY && Nat.eqb (stage i) 6 && Nat.eqb (stage j) 7 && Nat.ltb 124 (CC.cp_nx c) && (Nat.eqb (chain i) 1 || Nat.eqb (chain i) 2)
                 && CHA.foot_chk GT.NF G.HDECL c (BLK (chain i)) []
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 (BLK (chain i)) [] [(nbE, 0, nE)] STAT (Some nbE) c ps cj (BLK (chain i)) [] (BLK (chain i)) [])
                 && CL.ps_reg_is ps 10 nbE && CL.ps_reg_is ps 11 pE && CL.ps_reg_is ps 12 nE)%bool
              else false)%bool
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && CBA.exit_base_chk GT.NF RETPC c ps && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) []
           && ((Nat.eqb (stage i) 5 && Nat.eqb (chain i) 0) || (Nat.eqb (stage i) 7 && (Nat.eqb (chain i) 1 || Nat.eqb (chain i) 2) && Nat.ltb 124 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) FEXL))
           && CH2.blocks_eqb (nth i G.BLS []) (if (stage i <? 6)%nat then [] else BLK (chain i))
           && exit_cells (chain i) cells)%bool
      end
  end.
